using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;
public static class PerimeterCapture {
 static string O=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-07_C01_Perimeter/"));
 static void Shot(string name,Vector3 p,Vector3 target,float fov=75){var go=new GameObject("Perimeter_Review_Temporary");var c=go.AddComponent<Camera>();c.transform.position=p;c.transform.LookAt(target);c.nearClipPlane=.04f;c.farClipPlane=200;c.fieldOfView=fov;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.027f,.037f,.05f);c.GetUniversalAdditionalCameraData().renderPostProcessing=false;c.allowMSAA=true;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var prev=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(O+name+".png",tex.EncodeToPNG());}finally{RenderTexture.active=prev;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Before()=>Capture("Before");public static object After()=>Capture("After");
 static object Capture(string prefix){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Saved B5 edit scene required");Directory.CreateDirectory(O);var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var hidden=s.GetRootGameObjects().Where(g=>g.name.StartsWith("Player")).SelectMany(g=>g.GetComponentsInChildren<Renderer>()).ToDictionary(r=>r,r=>r.enabled);var center=new Vector3(-15,-82,-10);
 try{foreach(var r in hidden.Keys)r.enabled=false;Shot(prefix+"_Overview",new Vector3(-9.2f,-80.35f,-10),new Vector3(-20.3f,-79.6f,-4.9f));
 foreach(int a in new[]{50,145,230,280,325}){float rad=a*Mathf.Deg2Rad;var d=new Vector3(Mathf.Cos(rad),0,Mathf.Sin(rad));Shot(prefix+"_Zone_"+a,center+d*4.8f+Vector3.up*1.65f,center+d*8.95f+Vector3.up*1.5f,88);}
 var cab=root.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="CD-040_CFD_EmergencyCabinet");var target=cab.position+Vector3.up*.85f;Shot(prefix+"_EmergencyCabinet",target+cab.forward*2.2f+cab.right*.3f,target,48);
 if(prefix=="After"){
 foreach(var n in new[]{"Observation_Console_A","Clinical_PPE_Station","S1_VitalMonitor_18"}){var t=root.GetComponentsInChildren<Transform>().Single(x=>x.name==n);var target2=t.position+Vector3.up*(n.Contains("Vital")?1.05f:1.05f);Shot("After_Close_"+n,target2+t.forward*2.55f+t.right*.40f+Vector3.up*.15f,target2,48);}
 var analyzer=root.Find("C01_Experiment_Art/C01_Perimeter_Lab/Station_48/CP_OpticalAnalyzer");var at=analyzer.position+Vector3.up*.34f;Shot("After_Close_OpticalAnalyzer",at+analyzer.forward*1.45f+analyzer.right*.55f+Vector3.up*.65f,at,48);
 }
 }finally{foreach(var kv in hidden)kv.Key.enabled=kv.Value;EditorSceneManager.OpenScene(s.path);}return new{prefix,images=prefix=="After"?11:7,output=O};}
}
